} from '@ionic/react';
import { addOutline, createOutline, trashOutline, chevronBack, checkmarkCircle } from 'ionicons/icons';
import { useUser } from '../contexts/UserContext';
import { Supplier, getAllSuppliers, createSupplier, updateSupplier, deleteSupplier } from '../api/supplierApi';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useIonViewWillEnter } from '@ionic/react';

interface SupplierFormState {
  supplierName: string;
  contactName: string;
  phone: string;
  email: string;
  address: string;
  active: boolean; // '1' or '0' internally, boolean for UI toggle
}

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Convert to Hermosillo (UTC-7)
  const hermosilloTime = new Date(d.getTime() - 7 * 60 * 60 * 1000);
  return hermosilloTime.toLocaleString();
};

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();

  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [toastMessage, setToastMessage] = useState('');
  const [showToast, setShowToast] = useState(false);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [currentSupplier, setCurrentSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState<SupplierFormState>({
    supplierName: '',
    contactName: '',
    phone: '',
    email: '',
    address: '',
    active: true,
  });

  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const ITEMS_PER_PAGE = 20; // Example, adjust as needed

  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [supplierToDelete, setSupplierToDelete] = useState<Supplier | null>(null);

  const [popoverState, setPopoverState] = useState<{ showAlertPopover: boolean; showMailPopover: boolean; event?: Event; }>(
    { showAlertPopover: false, showMailPopover: false }
  );

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchSuppliers = async (reset = false) => {
    if (loading) return;
    setLoading(true);
    setError('');

    try {
      const allSuppliers = await getAllSuppliers(companyId);
      const filteredSuppliers = allSuppliers.filter(supplier =>
        supplier.supplierName.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (supplier.contactName && supplier.contactName.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (supplier.email && supplier.email.toLowerCase().includes(searchTerm.toLowerCase()))
      );

      if (reset) {
        setSuppliers(filteredSuppliers.slice(0, ITEMS_PER_PAGE));
        setPage(1);
        setHasMore(filteredSuppliers.length > ITEMS_PER_PAGE);
      } else {
        setSuppliers(filteredSuppliers);
        // For now, load all filtered items at once if not paginating
        setHasMore(false);
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al cargar proveedores');
      setShowToast(true);
      setToastMessage((err as Error).message ?? 'Error desconocido al cargar proveedores');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchSuppliers(true);
  });

  useEffect(() => {
    fetchSuppliers(true);
  }, [searchTerm, companyId]);

  const loadMoreItems = (ev: CustomEvent<void>) => {
    // In a real paginated scenario, you would fetch the next page here.
    // For this simple CRUD, we assume all data is fetched or handle a simple slice.
    // Since hasMore is set to false after initial fetch/filter, this won't run repeatedly.
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleCreateClick = () => {
    setFormState({
      supplierName: '',
      contactName: '',
      phone: '',
      email: '',
      address: '',
      active: true,
    });
    setCurrentSupplier(null);
    setShowCreateModal(true);
  };

  const handleEditClick = (supplier: Supplier) => {
    setFormState({
      supplierName: supplier.supplierName,
      contactName: supplier.contactName ?? '',
      phone: supplier.phone ?? '',
      email: supplier.email ?? '',
      address: supplier.address ?? '',
      active: supplier.active === '1',
    });
    setCurrentSupplier(supplier);
    setShowEditModal(true);
  };

  const handleSaveSupplier = async () => {
    if (!formState.supplierName.trim()) {
      setError('El nombre del proveedor es obligatorio.');
      setShowToast(true);
      setToastMessage('El nombre del proveedor es obligatorio.');
      return;
    }

    setSaving(true);
    setError('');

    const payload = {
      supplierName: formState.supplierName,
      contactName: formState.contactName || null,
      phone: formState.phone || null,
      email: formState.email || null,
      address: formState.address || null,
      active: formState.active ? '1' : '0',
      companyId: companyId,
    };

    try {
      if (currentSupplier) {
        await updateSupplier(currentSupplier.supplierId, payload);
        setToastMessage('Proveedor actualizado con éxito!');
      } else {
        await createSupplier(payload);
        setToastMessage('Proveedor creado con éxito!');
      }
      setShowToast(true);
      setShowCreateModal(false);
      setShowEditModal(false);
      fetchSuppliers(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al guardar proveedor.');
      setShowToast(true);
      setToastMessage((err as Error).message ?? 'Error desconocido al guardar proveedor.');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteRequest = (supplier: Supplier) => {
    setSupplierToDelete(supplier);
    setShowDeleteAlert(true);
  };

  const confirmDeleteSupplier = async () => {
    if (!supplierToDelete) return;

    setLoading(true);
    setError('');

    try {
      await deleteSupplier(supplierToDelete.supplierId, companyId);
      setToastMessage('Proveedor eliminado con éxito!');
      setShowToast(true);
      fetchSuppliers(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al eliminar proveedor.');
      setShowToast(true);
      setToastMessage((err as Error).message ?? 'Error desconocido al eliminar proveedor.');
    } finally {
      setLoading(false);
      setSupplierToDelete(null);
    }
  };

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          placeholder="Buscar proveedores"
          value={searchTerm}
          onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSearchTerm(e.detail.value!)}
          debounce={300}
        />

        {loading && suppliers.length === 0 ? (
          <div className="ion-text-center ion-padding">
            <IonSpinner name="crescent" />
            <p>Cargando proveedores...</p>
          </div>
        ) : suppliers.length === 0 ? (
          <div className="ion-text-center ion-padding">
            <p>No hay proveedores disponibles.</p>
          </div>
        ) : (
          <IonList className="supplier-list">
            {suppliers.map((supplier) => (
              <IonItem key={supplier.supplierId} className="supplier-item ion-activatable">
                <IonLabel>
                  <h2>{supplier.supplierName}</h2>
                  <p>Contacto: {supplier.contactName || 'N/A'}</p>
                  <p>Teléfono: {supplier.phone || 'N/A'}</p>
                  <p>Email: {supplier.email || 'N/A'}</p>
                  <p>Dirección: {supplier.address || 'N/A'}</p>
