                </IonLabel>
                <IonButton fill="clear" slot="end" onClick={() => handleEditClick(supplier)}>
                  <IonIcon icon={createOutline} />
                </IonButton>
                <IonButton fill="clear" color="danger" slot="end" onClick={() => handleDeleteRequest(supplier)}>
                  <IonIcon icon={trashOutline} />
                </IonButton>
