          <IonHeader>
            <IonToolbar>
              <IonButtons slot="start">
                <IonButton onClick={() => { setShowCreateModal(false); setShowEditModal(false); setCurrentSupplier(null); setError(''); }}>
                  <IonIcon icon={chevronBack} />
